// External Variable Definition (Global Scope, Static Duration)
// Initialized to 0 by default if no value is given.
int global_count = 0;

// Function 1: Reads and modifies the external variable
void increment_count() {
    global_count++;
}

// Function 2: Demonstrates persistence and shared access
int get_current_count() {
    return global_count; // Value persists across all calls
}

